// Check if appointment date/time has passed
const appointmentDate = $input.item.json.appointment_date;
const appointmentTime = $input.item.json.appointment_time;

// Combine date and time
const appointmentDateTime = new Date(`${appointmentDate}T${appointmentTime}`);
const now = new Date();

// Check if appointment was more than 1 hour ago
const hoursSince = (now - appointmentDateTime) / (1000 * 60 * 60);

if (hoursSince > 1) {
  // Appointment has passed - mark for completion
  return {
    json: {
      ...$input.item.json,
      shouldComplete: true,
      hoursSinceAppointment: Math.round(hoursSince * 10) / 10,
      currentTime: now.toISOString()
    }
  };
} else {
  // Appointment hasn't happened yet or just finished
  return {
    json: {
      ...$input.item.json,
      shouldComplete: false,
      hoursSinceAppointment: Math.round(hoursSince * 10) / 10
    }
  };
}

// Log what happened
const appointment = $input.item.json;

console.log('✅ Auto-completed appointment:', {
  id: appointment.id,
  patient_id: appointment.patient_id,
  date: appointment.appointment_date,
  time: appointment.appointment_time,
  service: appointment.reason_for_visit,
  hoursSince: appointment.hoursSinceAppointment
});

return {
  json: {
    success: true,
    appointmentId: appointment.id,
    message: `Completed appointment ${appointment.id}`,
    feedbackScheduled: true
  }
};
